var CH_DAY = 86400000;
var CH_LEVELS = ['#161B22', '#0E4429', '#006D32', '#26A641', '#39D353'];
var CH_MONTHS = ['1月','2月','3月','4月','5月','6月','7月','8月','9月','10月','11月','12月'];
var CH_WEEKDAYS = ['周日','周一','周二','周三','周四','周五','周六'];

function pad2(n){ return (n < 10 ? '0' : '') + n; }

function fromISO(s){
  var m = /^(\d{4})-(\d{1,2})-(\d{1,2})$/.exec(String(s == null ? '' : s).trim());
  if (!m) return null;
  var y = parseInt(m[1], 10), mo = parseInt(m[2], 10), da = parseInt(m[3], 10);
  if (mo < 1 || mo > 12 || da < 1 || da > 31) return null;
  var ts = Date.UTC(y, mo - 1, da);
  var d = new Date(ts);
  if (d.getUTCFullYear() !== y || d.getUTCMonth() !== mo - 1 || d.getUTCDate() !== da) return null;
  return ts;
}

function toISO(ts){
  var d = new Date(ts);
  return d.getUTCFullYear() + '-' + pad2(d.getUTCMonth() + 1) + '-' + pad2(d.getUTCDate());
}

function dow(ts){ return new Date(ts).getUTCDay(); }

function addDays(ts, n){ return ts + n * CH_DAY; }

function parseEntries(text){
  var lines = String(text == null ? '' : text).split(/\r?\n/);
  var map = {}, errors = [], order = [];
  for (var i = 0; i < lines.length; i++){
    var l = lines[i].trim();
    if (!l || l.charAt(0) === '#') continue;
    var m = /^([^\s,，:：\t]+)[\s,，:：\t]+(-?[\d.]+)$/.exec(l);
    if (!m){
      var only = fromISO(l);
      if (only !== null){ if (map[l] === undefined){ map[l] = 0; order.push(l); } map[l] += 1; continue; }
      errors.push({ line:i + 1, text:l, why:'格式应为 YYYY-MM-DD 数值' });
      continue;
    }
    var ts = fromISO(m[1]);
    if (ts === null){ errors.push({ line:i + 1, text:l, why:'日期非法：' + m[1] }); continue; }
    var v = parseFloat(m[2]);
    if (!isFinite(v)){ errors.push({ line:i + 1, text:l, why:'数值无法解析' }); continue; }
    var key = toISO(ts);
    if (map[key] === undefined){ map[key] = 0; order.push(key); }
    map[key] += v;
  }
  var entries = order.map(function(k){ return { date:k, ts:fromISO(k), value:map[k] }; });
  entries.sort(function(a, b){ return a.ts - b.ts; });
  return { entries:entries, map:map, errors:errors };
}

function rangeOf(entries, opt){
  opt = opt || {};
  var start = opt.start ? fromISO(opt.start) : null;
  var end = opt.end ? fromISO(opt.end) : null;
  if (!entries.length && (start === null || end === null)) return { start:null, end:null };
  if (start === null) start = entries[0].ts;
  if (end === null) end = entries[entries.length - 1].ts;
  if (end < start){ var t = start; start = end; end = t; }
  return { start:start, end:end };
}

function levelOf(value, max){
  if (!(value > 0)) return 0;
  if (!(max > 0)) return 1;
  var r = value / max;
  if (r <= 0.25) return 1;
  if (r <= 0.5) return 2;
  if (r <= 0.75) return 3;
  return 4;
}

function buildGrid(parsed, opt){
  opt = opt || {};
  var weekStart = opt.weekStart === 0 ? 0 : 1;
  var rg = rangeOf(parsed.entries, opt);
  if (rg.start === null) return { weeks:[], days:0, empty:true, weekStart:weekStart, start:null, end:null, max:0 };
  var lead = (dow(rg.start) - weekStart + 7) % 7;
  var gridStart = addDays(rg.start, -lead);
  var tail = (weekStart + 6 - dow(rg.end) + 7) % 7;
  var gridEnd = addDays(rg.end, tail);
  var max = 0;
  for (var e = 0; e < parsed.entries.length; e++){
    var t = parsed.entries[e].ts;
    if (t >= rg.start && t <= rg.end) max = Math.max(max, parsed.entries[e].value);
  }
  var weeks = [], week = [], count = 0;
  for (var ts = gridStart; ts <= gridEnd; ts = addDays(ts, 1)){
    var iso = toISO(ts);
    var inRange = ts >= rg.start && ts <= rg.end;
    var v = inRange && parsed.map[iso] !== undefined ? parsed.map[iso] : 0;
    week.push({ date:iso, ts:ts, value:inRange ? v : null, inRange:inRange, level:inRange ? levelOf(v, max) : -1, dow:dow(ts) });
    if (inRange) count++;
    if (week.length === 7){ weeks.push(week); week = []; }
  }
  if (week.length) weeks.push(week);
  return { weeks:weeks, days:count, empty:false, weekStart:weekStart, start:rg.start, end:rg.end, max:max };
}

function stats(parsed, grid){
  var total = 0, active = 0, best = null, weekday = [0,0,0,0,0,0,0], weekdayDays = [0,0,0,0,0,0,0];
  if (!grid || grid.empty) return { total:0, active:0, days:0, best:null, average:0, activeAverage:0, currentStreak:0, longestStreak:0, weekday:weekday, coverage:0 };
  var flat = [];
  for (var w = 0; w < grid.weeks.length; w++)
    for (var d = 0; d < grid.weeks[w].length; d++)
      if (grid.weeks[w][d].inRange) flat.push(grid.weeks[w][d]);
  for (var i = 0; i < flat.length; i++){
    var c = flat[i];
    total += c.value;
    weekday[c.dow] += c.value;
    weekdayDays[c.dow]++;
    if (c.value > 0){ active++; if (!best || c.value > best.value) best = { date:c.date, value:c.value }; }
  }
  var cur = 0, longest = 0, run = 0;
  for (var j = 0; j < flat.length; j++){
    if (flat[j].value > 0){ run++; longest = Math.max(longest, run); }
    else run = 0;
  }
  for (var k = flat.length - 1; k >= 0; k--){
    if (flat[k].value > 0) cur++;
    else break;
  }
  var wd = [];
  for (var q = 0; q < 7; q++) wd.push({ name:CH_WEEKDAYS[q], total:round2(weekday[q]), average: weekdayDays[q] ? round2(weekday[q] / weekdayDays[q]) : 0 });
  return {
    total: round2(total), active: active, days: flat.length,
    best: best, average: flat.length ? round2(total / flat.length) : 0,
    activeAverage: active ? round2(total / active) : 0,
    currentStreak: cur, longestStreak: longest,
    coverage: flat.length ? Math.round(active / flat.length * 1000) / 10 : 0,
    weekday: wd
  };
}

function round2(n){ return Math.round(n * 100) / 100; }

function monthLabels(grid){
  if (!grid || grid.empty) return [];
  var out = [], last = -1;
  for (var w = 0; w < grid.weeks.length; w++){
    var col = grid.weeks[w], first = null;
    for (var d = 0; d < col.length; d++){ if (col[d].inRange){ first = col[d]; break; } }
    if (!first) continue;
    var mo = new Date(first.ts).getUTCMonth();
    if (mo !== last){ out.push({ week:w, month:mo, name:CH_MONTHS[mo] }); last = mo; }
  }
  return out;
}

function escXml(s){
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function toSvg(grid, opt){
  opt = opt || {};
  var cell = opt.cell || 12, gap = opt.gap || 3, padL = 34, padT = 22, padB = 26;
  if (!grid || grid.empty) return '<svg xmlns="http://www.w3.org/2000/svg" width="200" height="80"></svg>';
  var W = padL + grid.weeks.length * (cell + gap) + 10;
  var H = padT + 7 * (cell + gap) + padB;
  var out = ['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + W + ' ' + H + '" width="100%" height="' + H + '" role="img" aria-label="日历热力图">'];
  out.push('<rect width="' + W + '" height="' + H + '" fill="#0A0A0B"/>');
  var labels = monthLabels(grid);
  for (var l = 0; l < labels.length; l++){
    out.push('<text x="' + (padL + labels[l].week * (cell + gap)) + '" y="' + (padT - 7) + '" fill="#71717A" font-size="10" font-family="system-ui,sans-serif">' + escXml(labels[l].name) + '</text>');
  }
  for (var r = 0; r < 7; r += 2){
    var dayIdx = (grid.weekStart + r) % 7;
    out.push('<text x="' + (padL - 6) + '" y="' + (padT + r * (cell + gap) + cell - 2) + '" fill="#71717A" font-size="9" text-anchor="end" font-family="system-ui,sans-serif">' + escXml(CH_WEEKDAYS[dayIdx].slice(1)) + '</text>');
  }
  for (var w = 0; w < grid.weeks.length; w++){
    for (var d = 0; d < grid.weeks[w].length; d++){
      var c = grid.weeks[w][d];
      var x = padL + w * (cell + gap), y = padT + d * (cell + gap);
      if (!c.inRange){
        out.push('<rect x="' + x + '" y="' + y + '" width="' + cell + '" height="' + cell + '" rx="2" fill="#0F1113"/>');
        continue;
      }
      out.push('<rect x="' + x + '" y="' + y + '" width="' + cell + '" height="' + cell + '" rx="2" fill="' + CH_LEVELS[c.level] + '"><title>' + escXml(c.date + '：' + c.value) + '</title></rect>');
    }
  }
  var lx = padL, ly = padT + 7 * (cell + gap) + 8;
  out.push('<text x="' + lx + '" y="' + (ly + 10) + '" fill="#71717A" font-size="10" font-family="system-ui,sans-serif">少</text>');
  for (var k = 0; k < CH_LEVELS.length; k++){
    out.push('<rect x="' + (lx + 20 + k * (cell + 3)) + '" y="' + ly + '" width="' + cell + '" height="' + cell + '" rx="2" fill="' + CH_LEVELS[k] + '"/>');
  }
  out.push('<text x="' + (lx + 26 + CH_LEVELS.length * (cell + 3)) + '" y="' + (ly + 10) + '" fill="#71717A" font-size="10" font-family="system-ui,sans-serif">多</text>');
  out.push('</svg>');
  return out.join('');
}

var CalendarHeatForgePure = {
  fromISO: fromISO, toISO: toISO, dow: dow, addDays: addDays, parseEntries: parseEntries,
  rangeOf: rangeOf, levelOf: levelOf, buildGrid: buildGrid, stats: stats, monthLabels: monthLabels,
  toSvg: toSvg, LEVELS: CH_LEVELS, WEEKDAYS: CH_WEEKDAYS, DAY: CH_DAY
};
if (typeof module !== 'undefined' && module.exports) module.exports = CalendarHeatForgePure;
if (typeof window !== 'undefined') window.CalendarHeatForgePure = CalendarHeatForgePure;
